using Kitsuneo.Core.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace Kitsuneo.Infrastructure.Persistence.Configurations;

public class PracticeAttemptConfiguration : IEntityTypeConfiguration<PracticeAttempt>
{
    public void Configure(EntityTypeBuilder<PracticeAttempt> builder)
    {
        builder.ToTable("practice_attempts");

        builder.HasKey(a => a.Id);

        // The Id is generated by the domain (Guid v7) in PracticeAttempt.Create
        builder.Property(a => a.Id)
            .ValueGeneratedNever();

        builder.HasOne<Phrase>()
            .WithMany()
            .HasForeignKey(a => a.PhraseId)
            .OnDelete(DeleteBehavior.Cascade);

        builder.Property(a => a.UserId)
            .IsRequired();

        builder.Property(a => a.Answer)
            .HasMaxLength(Phrase.MaxLength)
            .IsRequired();

        builder.Property(a => a.Accuracy)
            .IsRequired();

        builder.Property(a => a.PlayCount)
            .IsRequired();

        builder.Property(a => a.UsedSlowSpeed)
            .IsRequired();

        builder.Property(a => a.DurationMs)
            .IsRequired();

        // Stored as text through the enum convention in AppDbContext; null until rated
        builder.Property(a => a.Rating);

        builder.Property(a => a.CreatedAt)
            .IsRequired();

        // Serves the "first attempted today" count of the daily practice
        builder.HasIndex(a => new { a.UserId, a.CreatedAt });

        // Serves a phrase's attempt history
        builder.HasIndex(a => new { a.PhraseId, a.CreatedAt });
    }
}
